/**
 * @param {number[][]} grid
 * @param {number[][]} hits
 * @return {number[]}
 */
var hitBricks = function(grid, hits) {
    const R = grid.length, C = grid[0].length;
    const N = R * C;
    const parent = new Array(N + 1);
    const sz = new Array(N + 1);
    for (let i = 0; i <= N; i++) {
        parent[i] = i;
        sz[i] = i === N ? 0 : 1;
    }
    const find = (x) => {
        if (parent[x] !== x) parent[x] = find(parent[x]);
        return parent[x];
    };
    const union = (x, y) => {
        let px = find(x), py = find(y);
        if (px === py) return;
        if (sz[px] < sz[py]) {
            parent[px] = py;
            sz[py] += sz[px];
        } else {
            parent[py] = px;
            sz[px] += sz[py];
        }
    };
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    const connect = (i, j) => {
        const id = i * C + j;
        if (i === 0) union(id, N);
        for (const [di, dj] of dirs) {
            const ni = i + di, nj = j + dj;
            if (ni >= 0 && ni < R && nj >= 0 && nj < C && grid[ni][nj] === 1) {
                union(id, ni * C + nj);
            }
        }
    };
    for (const [x, y] of hits) grid[x][y]--;
    for (let i = 0; i < R; i++) {
        for (let j = 0; j < C; j++) {
            if (grid[i][j] === 1) connect(i, j);
        }
    }
    const result = new Array(hits.length);
    for (let k = hits.length - 1; k >= 0; k--) {
        const [x, y] = hits[k];
        grid[x][y]++;
        if (grid[x][y] !== 1) {
            result[k] = 0;
            continue;
        }
        const before = sz[find(N)];
        connect(x, y);
        const after = sz[find(N)];
        result[k] = Math.max(0, after - before - 1);
    }
    return result;
};
```

