/**
 * @param {number[]} arr
 * @return {number}
 */
var numFactoredBinaryTrees = function(arr) {
    const MOD = 1000000007n;
    arr.sort((a, b) => a - b);
    const n = arr.length;
    const dp = new Array(n).fill(1n);
    const index = new Map();
    for (let i = 0; i < n; i++) index.set(arr[i], i);
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < i; j++) {
            if (arr[i] % arr[j] === 0) {
                const right = arr[i] / arr[j];
                if (index.has(right)) {
                    const k = index.get(right);
                    dp[i] = (dp[i] + dp[j] * dp[k]) % MOD;
                }
            }
        }
    }
    let ans = 0n;
    for (let x of dp) ans = (ans + x) % MOD;
    return Number(ans);
};
