/**
 * @param {number} n
 * @return {number}
 */
var clumsy = function(n) {
    if (n === 1) return 1;
    if (n === 2) return 2;
    if (n === 3) return 6;
    let res = Math.floor(n * (n - 1) / (n - 2)) + (n - 3);
    n -= 4;
    while (n >= 4) {
        res += -Math.floor(n * (n - 1) / (n - 2)) + (n - 3);
        n -= 4;
    }
    if (n === 3) {
        res -= Math.floor(n * (n - 1) / (n - 2));
    } else if (n === 2) {
        res -= n * (n - 1);
    } else if (n === 1) {
        res -= n;
    }
    return res;
};
