```javascript
/**
 * @param {number} m
 * @param {number} k
 */
var MKAverage = function(m, k) {
    this.m = m;
    this.k = k;
    this.N = 100000;
    this.stream = [];
    this.total = 0;
    this.fenCnt = new Array(this.N + 1).fill(0);
    this.fenSum = new Array(this.N + 1).fill(0);
};

MKAverage.prototype.update = function(idx, delta) {
    const v = idx;
    while (idx <= this.N) {
        this.fenCnt[idx] += delta;
        this.fenSum[idx] += v * delta;
        idx += idx & -idx;
    }
};

MKAverage.prototype.queryCnt = function(idx) {
    let res = 0;
    while (idx > 0) {
        res += this.fenCnt[idx];
        idx -= idx & -idx;
    }
    return res;
};

MKAverage.prototype.querySum = function(idx) {
    let res = 0;
    while (idx > 0) {
        res += this.fenSum[idx];
        idx -= idx & -idx;
    }
    return res;
};

MKAverage.prototype.getSumSmallest = function(k) {
    if (k === 0) return 0;
    let lo = 1, hi = this.N, x = this.N;
    while (lo <= hi) {
        const mid = (lo + hi) >> 1;
        if (this.queryCnt(mid) >= k) {
            x = mid;
            hi = mid - 1;
        } else {
            lo = mid + 1;
        }
    }
    const prevCnt = this.queryCnt(x - 1);
    const prevSum = this.querySum(x - 1);
    return prevSum + (k - prevCnt) * x;
};

/** 
 * @param {number} num
 * @return {void}
 */
MKAverage.prototype.addElement = function(num) {
    this.stream.push(num);
    this.update(num, 1);
    this.total += num;
    if (this.stream.length > this.m) {
        const old = this.stream[this.stream.length - this.m - 1];
        this.update(old, -1);
        this.total -= old;
    }
};

/**
 * @return {number}
 */
MKAverage.prototype.calculateMKAverage = function() {
    if (this.stream.length < this.m) return -1;
    const smallK = this.getSumSmallest(this.k);
    const smallMK = this.getSumSmallest(this.m - this.k);
    const largeK = this.total - smallMK;
    const midSum = this.total - smallK - largeK;
    return Math.floor(midSum / (this.m - 2 * this.k));
};
```

