/**
 * @param {string[]} queries
 * @param {string[]} words
 * @return {number[]}
 */
var numSmallerByFrequency = function(queries, words) {
    const f = (s) => {
        let minChar = 'z';
        let count = 0;
        for (const c of s) {
            if (c < minChar) {
                minChar = c;
                count = 1;
            } else if (c === minChar) {
                count++;
            }
        }
        return count;
    };
    const wordFreqs = words.map(f).sort((a, b) => a - b);
    return queries.map(q => {
        const fq = f(q);
        let left = 0, right = wordFreqs.length;
        while (left < right) {
            const mid = (left + right) >> 1;
            if (wordFreqs[mid] <= fq) left = mid + 1;
            else right = mid;
        }
        return wordFreqs.length - left;
    });
};
