/**
 * @param {number[]} nums
 * @return {number}
 */
var maxScore = function(nums) {
    const m = nums.length;
    const n = m / 2;
    const gcd = (a, b) => b === 0 ? a : gcd(b, a % b);
    const memo = new Array(1 << m).fill(-1);
    memo[0] = 0;
    function dp(mask) {
        if (memo[mask] !== -1) return memo[mask];
        let remaining = 0;
        for (let i = 0; i < m; i++) if (mask & (1 << i)) remaining++;
        const k = remaining / 2;
        const op = n - k + 1;
        let maxVal = 0;
        for (let i = 0; i < m; i++) {
            if ((mask & (1 << i)) === 0) continue;
            for (let j = i + 1; j < m; j++) {
                if ((mask & (1 << j)) === 0) continue;
                const newMask = mask ^ (1 << i) ^ (1 << j);
                const score = op * gcd(nums[i], nums[j]) + dp(newMask);
                if (score > maxVal) maxVal = score;
            }
        }
        memo[mask] = maxVal;
        return maxVal;
    }
    return dp((1 << m) - 1);
};
