 * @param {number} numSlots
 * @return {number}
 */
var maximumANDSum = function(nums, numSlots) {
    const maxState = Math.pow(3, numSlots);
    let dp = new Array(maxState).fill(-1);
    dp[0] = 0;
    for (const num of nums) {
        const ndp = new Array(maxState).fill(-1);
        for (let state = 0; state < maxState; state++) {
            if (dp[state] < 0) continue;
            let temp = state;
            let p3 = 1;
            for (let slot = 0; slot < numSlots; slot++) {
                const occ = temp % 3;
                temp = Math.floor(temp / 3);
                if (occ < 2) {
                    const newState = state + p3;
                    const val = dp[state] + (num & (slot + 1));
                    if (val > ndp[newState]) ndp[newState] = val;
                }
                p3 *= 3;
            }
        }
        dp = ndp;
    }
    let ans = 0;
    for (const x of dp) if (x > ans) ans = x;
    return ans;
};
