/**
 * Definition for a binary tree node.
 * function TreeNode(val, left, right) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.left = (left===undefined ? null : left)
 *     this.right = (right===undefined ? null : right)
 * }
 */
/**
 * @param {TreeNode} root
 * @param {number} x
 * @param {number} y
 * @return {boolean}
 */
var isCousins = function(root, x, y) {
    function find(node, val, parent, depth) {
        if (!node) return null;
        if (node.val === val) return { parent, depth };
        const left = find(node.left, val, node, depth + 1);
        if (left) return left;
        return find(node.right, val, node, depth + 1);
    }
    const infoX = find(root, x, null, 0);
    const infoY = find(root, y, null, 0);
    return infoX.depth === infoY.depth && infoX.parent !== infoY.parent;
};
