/**
 * @param {number[][]} fruits
 * @param {number} startPos
 * @param {number} k
 * @return {number}
 */
var maxTotalFruits = function(fruits, startPos, k) {
    const n = fruits.length;
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] + fruits[i][1];
    }
    const getCost = (i, j) => {
        const left = fruits[i][0];
        const right = fruits[j][0];
        if (startPos >= left && startPos <= right) {
            return Math.min(startPos - left + right - left, right - startPos + right - left);
        } else if (startPos < left) {
            return right - startPos;
        } else {
            return startPos - left;
        }
    };
    let maxFruits = 0;
    let j = 0;
    for (let i = 0; i < n; i++) {
        j = Math.max(j, i);
        while (j < n && getCost(i, j) <= k) {
            j++;
        }
        if (j > i) {
            maxFruits = Math.max(maxFruits, prefix[j] - prefix[i]);
        }
    }
    return maxFruits;
};
