/**
 * @param {number[][]} grid
 * @return {number}
 */
var largestMagicSquare = function(grid) {
    const m = grid.length;
    const n = grid[0].length;
    const rowPre = Array.from({ length: m }, () => Array(n + 1).fill(0));
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            rowPre[i][j + 1] = rowPre[i][j] + grid[i][j];
        }
    }
    const colPre = Array.from({ length: m + 1 }, () => Array(n).fill(0));
    for (let j = 0; j < n; j++) {
        for (let i = 0; i < m; i++) {
            colPre[i + 1][j] = colPre[i][j] + grid[i][j];
        }
    }
    for (let k = Math.min(m, n); k >= 1; k--) {
        for (let i = 0; i <= m - k; i++) {
            for (let j = 0; j <= n - k; j++) {
                const sum = rowPre[i][j + k] - rowPre[i][j];
                let magic = true;
                for (let r = i; r < i + k; r++) {
                    if (rowPre[r][j + k] - rowPre[r][j] !== sum) {
                        magic = false;
                        break;
                    }
                }
                if (!magic) continue;
                for (let c = j; c < j + k; c++) {
                    if (colPre[i + k][c] - colPre[i][c] !== sum) {
                        magic = false;
                        break;
                    }
                }
                if (!magic) continue;
                let d1 = 0, d2 = 0;
                for (let d = 0; d < k; d++) {
                    d1 += grid[i + d][j + d];
                    d2 += grid[i + d][j + k - 1 - d];
                }
                if (d1 === sum && d2 === sum) return k;
            }
        }
    }
    return 1;
};
