/**
 * @param {character[][]} seats
 * @return {number}
 */
var maxStudents = function(seats) {
    const m = seats.length;
    const n = seats[0].length;
    const avail = new Array(m).fill(0);
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (seats[i][j] === '.') {
                avail[i] |= (1 << j);
            }
        }
    }
    const validMasks = [];
    for (let mask = 0; mask < (1 << n); mask++) {
        if ((mask & (mask << 1)) === 0) {
            validMasks.push(mask);
        }
    }
    const popcount = (mask) => {
        let cnt = 0;
        while (mask) {
            cnt += mask & 1;
            mask >>= 1;
        }
        return cnt;
    };
    let prevDp = new Array(1 << n).fill(-Infinity);
    prevDp[0] = 0;
    for (let i = 0; i < m; i++) {
        const currDp = new Array(1 << n).fill(-Infinity);
        for (const mask of validMasks) {
            if ((mask & avail[i]) !== mask) continue;
            const bits = popcount(mask);
            for (let pmask = 0; pmask < (1 << n); pmask++) {
                if (prevDp[pmask] === -Infinity) continue;
                if ((mask & (pmask << 1)) === 0 && (mask & (pmask >> 1)) === 0) {
                    currDp[mask] = Math.max(currDp[mask], prevDp[pmask] + bits);
                }
            }
        }
        prevDp = currDp;
    }
    let ans = 0;
    for (const v of prevDp) {
        if (v > ans) ans = v;
    }
    return ans;
};
