/**
 * @param {number[]} flowers
 * @param {number} newFlowers
 * @param {number} target
 * @param {number} full
 * @param {number} partial
 * @return {number}
 */
var maximumBeauty = function(flowers, newFlowers, target, full, partial) {
    const n = flowers.length;
    const fl = flowers.map(f => Math.min(f, target)).sort((a, b) => a - b);
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] + fl[i];
    }
    let p = n;
    for (let i = 0; i < n; i++) {
        if (fl[i] === target) {
            p = i;
            break;
        }
    }
    let ans = 0;
    for (let m = 0; m <= p; m++) {
        const cost = (n - m) * target - (prefix[n] - prefix[m]);
        if (cost > newFlowers) continue;
        const rem = newFlowers - cost;
        if (m === 0) {
            ans = Math.max(ans, n * full);
            continue;
        }
        let lo = 0, hi = target - 1, bestx = 0;
        while (lo <= hi) {
            const mid = Math.floor((lo + hi) / 2);
            let l = 0, r = m;
            while (l < r) {
                const md = Math.floor((l + r) / 2);
                if (fl[md] < mid) l = md + 1;
                else r = md;
            }
            const pos = l;
            const cst = mid * pos - prefix[pos];
            if (cst <= rem) {
                bestx = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        ans = Math.max(ans, (n - m) * full + bestx * partial);
    }
    return ans;
};
