var minMalwareSpread = function(graph, initial) {
    const n = graph.length;
    let minCount = Infinity;
    let ans = n;
    const simulate = (remove) => {
        const visited = new Array(n).fill(false);
        visited[remove] = true;
        const queue = [];
        for (const node of initial) {
            if (node !== remove) {
                queue.push(node);
                visited[node] = true;
            }
        }
        let count = queue.length;
        let head = 0;
        while (head < queue.length) {
            const u = queue[head++];
            for (let v = 0; v < n; v++) {
                if (graph[u][v] && !visited[v]) {
                    visited[v] = true;
                    queue.push(v);
                    count++;
                }
            }
        }
        return count;
    };
    for (const node of initial) {
        const count = simulate(node);
        if (count < minCount || (count === minCount && node < ans)) {
            minCount = count;
            ans = node;
        }
    }
    return ans;
