/**
 * @param {number} maxTime
 * @param {number[][]} edges
 * @param {number[]} passingFees
 * @return {number}
 */
var minCost = function(maxTime, edges, passingFees) {
    const n = passingFees.length;
    const INF = Number.MAX_SAFE_INTEGER;
    const dp = Array.from({length: maxTime + 1}, () => Array(n).fill(INF));
    dp[0][0] = passingFees[0];
    const adj = Array.from({length: n}, () => []);
    for (const [x, y, time] of edges) {
        adj[x].push([y, time]);
        adj[y].push([x, time]);
    }
    for (let t = 0; t <= maxTime; t++) {
        for (let u = 0; u < n; u++) {
            if (dp[t][u] === INF) continue;
            for (const [v, w] of adj[u]) {
                if (t + w <= maxTime) {
                    dp[t + w][v] = Math.min(dp[t + w][v], dp[t][u] + passingFees[v]);
                }
            }
        }
    }
    let ans = INF;
    for (let t = 0; t <= maxTime; t++) {
        ans = Math.min(ans, dp[t][n - 1]);
    }
    return ans === INF ? -1 : ans;
};
