 * @param {TreeNode} root
 * @return {number}
 */
var minDepth = function(root) {
    if (!root) return 0;
    const q = [root];
    let front = 0;
    let depth = 1;
    while (front < q.length) {
        const levelEnd = q.length;
        while (front < levelEnd) {
            const node = q[front++];
            if (!node.left && !node.right) return depth;
            if (node.left) q.push(node.left);
            if (node.right) q.push(node.right);
        }
        depth++;
    }
    return 0;
};
