/**
 * @param {number[]} nums
 * @return {number}
 */
var numOfWays = function(nums) {
    const MOD = 1000000007n;
    const n = nums.length;
    const comb = Array.from({length: n + 1}, () => new Array(n + 1).fill(0n));
    for (let i = 0; i <= n; i++) {
        comb[i][0] = 1n;
        for (let j = 1; j <= i; j++) {
            comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD;
        }
    }
    function dfs(arr) {
        const m = arr.length;
        if (m <= 2) return 1n;
        const root = arr[0];
        const left = [];
        const right = [];
        for (let i = 1; i < m; i++) {
            if (arr[i] < root) left.push(arr[i]);
            else right.push(arr[i]);
        }
        const ways = comb[m - 1][left.length] * dfs(left) % MOD * dfs(right) % MOD;
        return ways;
    }
    const total = dfs(nums);
    return Number((total - 1n + MOD) % MOD);
};
