/**
 * @param {string} s
 * @return {string[]}
 */
var removeInvalidParentheses = function(s) {
    let leftRem = 0, rightRem = 0;
    for (const c of s) {
        if (c === '(') {
            leftRem++;
        } else if (c === ')') {
            if (leftRem > 0) leftRem--;
            else rightRem++;
        }
    }
    const unique = new Set();
    function dfs(index, leftRem, rightRem, open, path) {
        if (index === s.length) {
            if (leftRem === 0 && rightRem === 0 && open === 0) {
                unique.add(path);
            }
            return;
        }
        const c = s[index];
        if ((c === '(' && leftRem > 0) || (c === ')' && rightRem > 0)) {
            dfs(index + 1, leftRem - (c === '(' ? 1 : 0), rightRem - (c === ')' ? 1 : 0), open, path);
        }
        if (c !== '(' && c !== ')') {
            dfs(index + 1, leftRem, rightRem, open, path + c);
        } else if (c === '(') {
            dfs(index + 1, leftRem, rightRem, open + 1, path + c);
        } else if (open > 0) {
            dfs(index + 1, leftRem, rightRem, open - 1, path + c);
        }
    }
    dfs(0, leftRem, rightRem, 0, '');
    return Array.from(unique);
};
