    function generateSubsets(idx, chosen) {
        if (idx === digits.length) {
            let len = 0;
            for (const d of chosen) len += d;
            if (len === 0 || len > 7) return;
            const arr = [];
            for (const d of chosen) {
                for (let k = 0; k < d; k++) arr.push(d);
