/**
 * @param {string[]} stickers
 * @param {string} target
 * @return {number}
 */
var minStickers = function(stickers, target) {
    const n = target.length;
    const N = 1 << n;
    const dist = new Array(N).fill(-1);
    dist[0] = 0;
    const q = [0];
    let qi = 0;
    const stickerCounts = stickers.map(s => {
        const cnt = new Array(26).fill(0);
        for (const c of s) cnt[c.charCodeAt(0) - 97]++;
        return cnt;
    });
    while (qi < q.length) {
        const mask = q[qi++];
        if (mask === N - 1) return dist[mask];
        for (const cnt of stickerCounts) {
            const remain = cnt.slice();
            let newMask = mask;
            for (let i = 0; i < n; i++) {
                if ((mask & (1 << i)) === 0) {
                    const c = target.charCodeAt(i) - 97;
                    if (remain[c] > 0) {
                        remain[c]--;
                        newMask |= (1 << i);
                    }
                }
            }
            if (dist[newMask] === -1) {
                dist[newMask] = dist[mask] + 1;
                q.push(newMask);
                if (newMask === N - 1) return dist[newMask];
            }
        }
    }
    return -1;
};
