    const size = n * 3;
    const g = Array.from({ length: size }, () => Array(size).fill(0));
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            const r = i * 3, c = j * 3;
            if (grid[i][j] === '/') {
                g[r][c + 2] = 1;
                g[r + 1][c + 1] = 1;
                g[r + 2][c] = 1;
            } else if (grid[i][j] === '\\') {
                g[r][c] = 1;
                g[r + 1][c + 1] = 1;
                g[r + 2][c + 2] = 1;
            }
        }
    }
    let count = 0;
    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    const dfs = (x, y) => {
        if (x < 0 || x >= size || y < 0 || y >= size || g[x][y] === 1) return;
        g[x][y] = 1;
        for (const [dx, dy] of dirs) dfs(x + dx, y + dy);
    };
    for (let i = 0; i < size; i++) {
        for (let j = 0; j < size; j++) {
            if (g[i][j] === 0) {
                count++;
                dfs(i, j);
            }
        }
    }
    return count;
