/**
 * @param {number} n
 * @param {number} firstPlayer
 * @param {number} secondPlayer
 * @return {number[]}
 */
var earliestAndLatest = function(n, firstPlayer, secondPlayer) {
    const memo = new Map();
    function dp(curN, a, b) {
        if (a > b) {
            const tmp = a;
            a = b;
            b = tmp;
        }
        if (a + b === curN + 1) return [1, 1];
        const key = curN + ',' + a + ',' + b;
        if (memo.has(key)) return memo.get(key);
        const free = [];
        const fixed = [];
        for (let i = 1; i <= curN; i++) {
            const j = curN + 1 - i;
            if (i > j) continue;
            if (i === j) {
                fixed.push(i);
            } else {
                const hasA = (i === a || j === a);
                const hasB = (i === b || j === b);
                if (hasA || hasB) {
                    if (i === a || i === b) fixed.push(i);
                    else fixed.push(j);
                } else {
                    free.push([i, j]);
                }
            }
        }
        const k = free.length;
        const poss = new Set();
        for (let mask = 0; mask < (1 << k); mask++) {
            const winners = fixed.slice();
            for (let f = 0; f < k; f++) {
                if (mask & (1 << f)) winners.push(free[f][0]);
                else winners.push(free[f][1]);
            }
            let cntA = 0, cntB = 0;
            for (const w of winners) {
                if (w < a) cntA++;
                if (w < b) cntB++;
            }
            const na = cntA + 1;
            const nb = cntB + 1;
            poss.add(na + ',' + nb);
        }
        let minR = Infinity, maxR = -Infinity;
        const nextN = (curN + 1) >> 1;
        for (const p of poss) {
            const comma = p.indexOf(',');
            const na = +p.substring(0, comma);
            const nb = +p.substring(comma + 1);
            const rec = dp(nextN, na, nb);
            minR = Math.min(minR, rec[0] + 1);
            maxR = Math.max(maxR, rec[1] + 1);
        }
        const res = [minR, maxR];
        memo.set(key, res);
        return res;
    }
    return dp(n, firstPlayer, secondPlayer);
};
