/**
 * @param {number[]} nums
 * @param {number[][]} edges
 * @return {number[]}
 */
var getCoprimes = function(nums, edges) {
    const n = nums.length;
    const graph = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        graph[u].push(v);
        graph[v].push(u);
    }
    const gcd = (a, b) => {
        while (b) {
            const t = b;
            b = a % b;
            a = t;
        }
        return a;
    };
    const coprimes = Array.from({ length: 51 }, () => []);
    for (let i = 1; i <= 50; i++) {
        for (let j = 1; j <= 50; j++) {
            if (gcd(i, j) === 1) coprimes[i].push(j);
        }
    }
    const last = Array.from({ length: 51 }, () => []);
    const ans = new Array(n).fill(-1);
    const stack = [[0, -1, 0, false]];
    while (stack.length) {
        const [node, par, dep, isExit] = stack.pop();
        const val = nums[node];
        if (isExit) {
            last[val].pop();
            continue;
        }
        let bestDepth = -1;
        let bestNode = -1;
        for (const cop of coprimes[val]) {
            const stk = last[cop];
            if (stk.length) {
                const [anc, d] = stk[stk.length - 1];
                if (d > bestDepth) {
                    bestDepth = d;
                    bestNode = anc;
                }
            }
        }
        ans[node] = bestNode;
        last[val].push([node, dep]);
        stack.push([node, par, dep, true]);
        const children = graph[node];
        for (let i = children.length - 1; i >= 0; i--) {
            const child = children[i];
            if (child !== par) stack.push([child, node, dep + 1, false]);
        }
    }
    return ans;
};
