/**
 * @param {string[]} words
 * @param {string} result
 * @return {boolean}
 */
var isSolvable = function(words, result) {
    const maxW = Math.max(...words.map(w => w.length));
    if (maxW > result.length) return false;
    const lead = new Set();
    for (const w of words) {
        if (w.length > 1) lead.add(w[0]);
    }
    if (result.length > 1) lead.add(result[0]);
    const wds = words.map(w => w.split('').reverse());
    const res = result.split('').reverse();
    const assign = {};
    const used = Array(10).fill(false);
    function dfs(col, row, sum) {
        if (col === res.length) {
            return sum === 0;
        }
        if (row === wds.length) {
            const digit = sum % 10;
            const carry = Math.floor(sum / 10);
            const c = res[col];
            if (assign[c] !== undefined) {
                if (assign[c] !== digit) return false;
                return dfs(col + 1, 0, carry);
            } else {
                if (used[digit] || (digit === 0 && lead.has(c))) return false;
                assign[c] = digit;
                used[digit] = true;
                const ok = dfs(col + 1, 0, carry);
                delete assign[c];
                used[digit] = false;
                return ok;
            }
        }
        const word = wds[row];
        if (col >= word.length) {
            return dfs(col, row + 1, sum);
        }
        const c = word[col];
        if (assign[c] !== undefined) {
            return dfs(col, row + 1, sum + assign[c]);
        } else {
            for (let d = 0; d < 10; d++) {
                if (!used[d] && !(d === 0 && lead.has(c))) {
                    assign[c] = d;
                    used[d] = true;
                    if (dfs(col, row + 1, sum + d)) return true;
                    delete assign[c];
                    used[d] = false;
                }
            }
            return false;
        }
    }
    return dfs(0, 0, 0);
};
