/**
 * @param {number} n
 * @param {number[]} leftChild
 * @param {number[]} rightChild
 * @return {boolean}
 */
var validateBinaryTreeNodes = function(n, leftChild, rightChild) {
    const children = new Set();
    for (let i = 0; i < n; i++) {
        const left = leftChild[i];
        const right = rightChild[i];
        if (left !== -1) {
            if (children.has(left)) return false;
            children.add(left);
        }
        if (right !== -1) {
            if (children.has(right)) return false;
            children.add(right);
        }
    }
    if (children.size !== n - 1) return false;
    let root = -1;
    for (let i = 0; i < n; i++) {
        if (!children.has(i)) {
            root = i;
            break;
        }
    }
    const visited = new Set();
    const queue = [root];
    visited.add(root);
    while (queue.length) {
        const node = queue.shift();
        const left = leftChild[node];
        const right = rightChild[node];
        if (left !== -1) {
            if (visited.has(left)) return false;
            visited.add(left);
            queue.push(left);
        }
        if (right !== -1) {
            if (visited.has(right)) return false;
            visited.add(right);
            queue.push(right);
        }
    }
    return visited.size === n;
};
